  for(const b of barrels){ctx.save();ctx.translate(b.x,b.y);ctx.scale(b.s,b.s);ctx.globalAlpha=.66;ctx.fillStyle='#11171b';ctx.strokeStyle='#52606a';ctx.lineWidth=1.2;ctx.beginPath();ctx.ellipse(0,-15,17,6,0,0,TAU);ctx.fill();ctx.stroke();ctx.fillRect(-17,-15,34,31);ctx.strokeRect(-17,-15,34,31);ctx.beginPath();ctx.ellipse(0,16,17,6,0,0,TAU);ctx.fill();ctx.stroke();ctx.strokeStyle='#78272a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-16,-4);ctx.lineTo(16,-4);ctx.stroke();ctx.globalAlpha=.42;ctx.fillStyle='#c86f54';ctx.fillRect(-2,-13,3,27);ctx.restore();}
  // containment fence / ruined rail at lower edge
  ctx.globalAlpha=.34;ctx.strokeStyle='#6a747a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(W*.60,bottom-9);ctx.lineTo(W,bottom-34);ctx.moveTo(W*.63,bottom+4);ctx.lineTo(W,bottom-21);ctx.stroke();ctx.lineWidth=1;for(let x=W*.64;x<W;x+=18){ctx.beginPath();ctx.moveTo(x,bottom-16);ctx.lineTo(x+18,bottom-39);ctx.stroke();}
