  // biohazard plate
  ctx.save();ctx.translate(W-43,H*.66);ctx.rotate(-.05);ctx.globalAlpha=.28;ctx.fillStyle='#332315';ctx.strokeStyle='#9b6339';ctx.lineWidth=1;ctx.fillRect(-23,-17,46,34);ctx.strokeRect(-23,-17,46,34);ctx.fillStyle='#d49353';ctx.font='1000 7px system-ui';ctx.textAlign='center';ctx.fillText('BIOHAZARD',0,10);ctx.font='1000 15px system-ui';ctx.fillText('☣',0,-2);ctx.restore();
  ctx.restore();
