function updateWorldSites(dt){
 worldSiteHintCd=Math.max(0,worldSiteHintCd-dt);
 for(const s of worldSites){
  s.pulse+=dt*3;if(s.claimed||s.arenaHidden)continue;
  if(s.active){if(s.type==='zoneEvent')updateZoneEventSite(s,dt);continue;}
  const d=Math.hypot(player.x-s.x,player.y-s.y),inside=d<=s.r;
  const encounter=s.type==='hotspot'||s.type==='zoneEvent'||s.type==='rift';
  const locked=encounter&&!directorCanStart('rift'),full=s.type==='regen'&&player.hp>=player.maxHp;
  if(inside&&!locked&&!full)s.hold=Math.min(s.need,s.hold+dt);else s.hold=Math.max(0,s.hold-dt*.8);
  if(s.hold<s.need||locked||full)continue;
  if(s.type==='hotspot'){activateHotspot(s);s.initialCount=s.remaining;}
  else if(s.type==='zoneEvent'){activateZoneEvent(s);s.initialCount=s.remaining;}
  else if(s.type==='rift'){if(spawnGeneRift(1,s))completeGeneRift();}
  else completeWorldSite(s);
 }
}
const SITE_ART_V422={bioChest:['pickups/capsule_knowledge',42],regen:['pickups/capsule_health',42],shield:['pickups/capsule_shield',42],rift:['pickups/dna_large',46],hotspot:['vfx/reward_ring',64],zoneEvent:['vfx/reward_beacon',72]};
function drawSiteArtV422(s){
 const def=SITE_ART_V422[s.type];if(!def)return;
 const [key,size]=def,c=worldSiteColor(s),near=Math.hypot(player.x-s.x,player.y-s.y)<s.r+55;
 const active=s.active&&(s.type==='hotspot'||s.type==='zoneEvent');
 const q=active?1:clamp((s.hold||0)/(s.need||1),0,1),locked=!active&&(s.type==='hotspot'||s.type==='zoneEvent'||s.type==='rift')&&!s.active&&!directorCanStart('rift');
 ctx.save();ctx.translate(s.x,s.y);ctx.fillStyle='#050b14';ctx.globalAlpha=.30;ctx.beginPath();ctx.arc(0,0,s.r,0,TAU);ctx.fill();
 // The complete perimeter is also the exact activation radius.
 ctx.globalAlpha=locked?.36:.76;ctx.strokeStyle=c;ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(0,0,s.r,0,TAU);ctx.stroke();
 if(q>0){ctx.globalAlpha=.15;ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,s.r,-Math.PI/2,-Math.PI/2+TAU*q);ctx.closePath();ctx.fill();ctx.globalAlpha=.98;ctx.strokeStyle=c;ctx.lineWidth=3.3;ctx.beginPath();ctx.arc(0,0,s.r,-Math.PI/2,-Math.PI/2+TAU*q);ctx.stroke();}
 ctx.restore();
 // Real pickup art, deliberately distinct from physical scenery.
 stamp(key,s.x,s.y-7-Math.sin(s.pulse)*1.2,size,0,active?.72:1);
 ctx.save();ctx.textAlign='center';ctx.font='800 6px system-ui';ctx.lineWidth=2.7;ctx.strokeStyle='#03060a';ctx.fillStyle=c;
 const label=s.type==='zoneEvent'?'REWARD CHALLENGE':worldSiteLabel(s);ctx.strokeText(label,s.x,s.y+s.r+10);ctx.fillText(label,s.x,s.y+s.r+10);
 if(near||active){let status=active?'DEFEAT '+s.remaining+' · CLAIM REWARD':s.type==='regen'&&player.hp>=player.maxHp?'HP FULL':locked?'LOCKED · ENCOUNTER':q>0?Math.floor(q*100)+'%':s.type==='zoneEvent'||s.type==='hotspot'?'HOLD TO START CHALLENGE':'STAND INSIDE TO ABSORB';ctx.font='700 5.5px system-ui';ctx.fillStyle='#edf6ff';ctx.strokeText(status,s.x,s.y+s.r+19);ctx.fillText(status,s.x,s.y+s.r+19);}
 ctx.restore();
}
function drawWorldSites(){
 const vr=cameraRect(110);
 for(const s of worldSites){if(s.claimed||s.arenaHidden||s.x<vr.l||s.x>vr.r||s.y<vr.t||s.y>vr.b||s.type==='rift'&&s.active)continue;drawSiteArtV422(s);}
}
function objectivePointerCandidates(){
  const a=[];if(rift)a.push({x:rift.x,y:rift.y,label:'RIFT',color:'#ff75df',priority:100});if(breachGate)a.push({x:breachGate.x,y:breachGate.y,label:'GATE',color:'#86e7ff',priority:110});
  if(contractNodes.length){const n=[...contractNodes].sort((x,y)=>dist2(player,x)-dist2(player,y))[0];if(n)a.push({x:n.x,y:n.y,label:'CORE',color:'#83ff98',priority:95});}
  for(const type of ['zoneEvent','hotspot','bioChest','regen']){
    const choices=worldSites.filter(s=>s.type===type&&!s.claimed&&!s.arenaHidden).sort((x,y)=>dist2(player,x)-dist2(player,y));const s=choices[0];if(!s)continue;
    const pr=type==='zoneEvent'?(s.active?94:74):type==='hotspot'?(s.active?88:66):type==='bioChest'?62:52;a.push({x:s.x,y:s.y,label:type==='zoneEvent'?zoneEventDef(s).label:type==='hotspot'?'NEST':type==='bioChest'?'CHEST':'HEAL',color:worldSiteColor(s),priority:pr});
  }
  return a.sort((p,q)=>q.priority-p.priority||((p.x-player.x)**2+(p.y-player.y)**2)-((q.x-player.x)**2+(q.y-player.y)**2)).slice(0,3);
}
function drawObjectivePointers(){
  const margin=34,cx=W*.5,cy=H*.5,vr=cameraRect(36);let slot=0;
  for(const o of objectivePointerCandidates()){if(o.x>=vr.l&&o.x<=vr.r&&o.y>=vr.t&&o.y<=vr.b)continue;let dx=o.x-player.x,dy=o.y-player.y,a=Math.atan2(dy,dx),rx=Math.max(20,W*.5-margin),ry=Math.max(20,H*.5-100),scale=Math.min(rx/Math.max(.001,Math.abs(Math.cos(a))),ry/Math.max(.001,Math.abs(Math.sin(a))));let x=clamp(cx+Math.cos(a)*scale,margin,W-margin),y=clamp(cy+Math.sin(a)*scale,110,H-86);const distance=Math.round(Math.hypot(dx,dy));ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.globalAlpha=.82;ctx.fillStyle=o.color;ctx.shadowBlur=12;ctx.shadowColor=o.color;ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(-4,-7);ctx.lineTo(-1,0);ctx.lineTo(-4,7);ctx.closePath();ctx.fill();ctx.rotate(-a);ctx.shadowBlur=0;ctx.font='1000 7px system-ui';ctx.textAlign='center';ctx.fillStyle='#f4f7fa';ctx.fillText(o.label+' '+distance,-Math.cos(a)*3,18+slot*0);ctx.restore();slot++;}
}
function updateBreachGate(dt){
  if(!breachGate)return;
  let d=Math.hypot(player.x-breachGate.x,player.y-breachGate.y);
  if(d<breachGate.r+player.r+8)breachGate.hold=Math.min(breachGate.need,breachGate.hold+dt);
  else breachGate.hold=Math.max(0,breachGate.hold-dt*.7);
  let pct=Math.floor(breachGate.hold/breachGate.need*100);
  $('objectiveBadge').textContent='BREACH GATE · '+pct+'%';
  if(breachGate.hold>=breachGate.need){
    breachGate=null;$('objectiveBadge').style.display='none';win();
  }
}

function spawnBiomeHazard(){
  if(!directorCanStart('hazard'))return false;
  if(meta.route==='cryo'){
    directorHold(.75);for(let i=0;i<2;i++){let p=worldPointInView(70);biomeHazards.push({kind:'cryo',x:p.x,y:p.y,r:42,warn:.85,active:4.0,tick:0});}
    flash('CRYO LOCK · KEEP MOVING',650);
  }else if(meta.route==='inferno'){
    directorHold(.75);for(let i=0;i<2;i++){let p=worldPointInView(70);biomeHazards.push({kind:'magma',x:p.x,y:p.y,r:38,warn:.75,active:2.8,tick:0});}
    flash('THERMAL VENT · MOVE',650);
  }else if(meta.route==='gene'){
    if(!rift){if(!spawnGeneRift(2))return false;flash('GENE RESONANCE',650);}
    else{
      directorHold(.75);for(let i=0;i<10;i++){let p=worldPointAroundPlayer(70,Math.min(W,H)*.46);spawnXPV415(p.x,p.y,2.2,12,0);}
      flash('GENE BLOOM · FREE DNA',650);
    }
  }
  return true;
}
function updateBiomeHazards(dt){
  player.envSlow=Math.max(0,(player.envSlow||0)-dt);
  biomeHazardCd-=dt;
  if(biomeHazardCd<=0&&!extractionMode){
    if(spawnBiomeHazard())biomeHazardCd=meta.route==='cryo'?13:meta.route==='gene'?16:meta.route==='inferno'?9:999;
    else biomeHazardCd=.8;
  }
  for(const z of biomeHazards){
    if(z.warn>0){z.warn-=dt;continue}
    z.active-=dt;z.tick-=dt;
    let inside=Math.hypot(player.x-z.x,player.y-z.y)<z.r+player.r;
    if(inside&&z.kind==='cryo'){let slow=.22*(1-Math.min(.40,routeMods.cryoResist||0));player.envSlow=Math.max(player.envSlow,slow);}
    if(inside&&z.kind==='magma'&&z.tick<=0){let heat=Math.max(3,(8+Math.min(12,Math.max(0,meta.stage-1)))*(1-Math.min(.18,routeMods.heatResist||0)));playerDamage(heat);z.tick=.42;cameraShake=Math.max(cameraShake,2.5);}
  }
  biomeHazards=biomeHazards.filter(z=>z.warn>0||z.active>0);
}

function spawnGeneRift(tier=1,preferredSite=null){
  if(rift||ended||!directorCanStart('rift'))return false;
  let site=preferredSite||worldSites.filter(s=>s.type==='rift'&&!s.claimed&&!s.active).sort((a,b)=>dist2(player,a)-dist2(player,b))[0];
  let x,y;if(site){x=site.x;y=site.y;site.active=true}else{const p=sitePointV422({r:30,preferred:worldPointAroundPlayer(145,Math.min(W,H)*.72),minCenter:0,minSep:95});if(!p)return false;x=p.x;y=p.y;}
  directorHold(.85);rift={x,y,tier,life:18+tier*2,hold:0,need:1.15,r:30,siteId:site?.id||0};
  $('objectiveBadge').style.display='block';$('objectiveBadge').textContent='GENE RIFT · Approach to absorb';
  flash('GENE RIFT DETECTED · FOLLOW MARKER',900);beep(660,.09,'triangle',.03);
  for(let i=0;i<18;i++)particles.push({kind:'rift',x,y,vx:rand(-45,45),vy:rand(-45,45),r:rand(1.5,3.5),life:rand(.35,.8)});
  return true;
}
function completeGeneRift(){
  if(!rift)return;
  const reward=10+rift.tier*5;
  dnaTotal+=reward; player.hp=Math.min(player.maxHp,player.hp+12+rift.tier*4);
  rerolls=Math.min(4,rerolls+1); activeReady=Math.max(0,activeReady-(1.2+rift.tier*.35)); predation=Math.min(100,predation+8+rift.tier*3); lootSweep=Math.max(lootSweep,2.4); riftSuccess++;
  particles.push({kind:'deathRing',x:rift.x,y:rift.y,r:6,max:52,life:.48,maxLife:.48});
  for(let i=0;i<28;i++)particles.push({kind:'rift',x:rift.x,y:rift.y,vx:rand(-95,95),vy:rand(-95,95),r:rand(1.8,4.2),life:rand(.3,.75)});
  flash('RIFT ABSORBED · +'+reward+' DNA',1100);beep(920,.12,'triangle',.04);
  if(runTelemetry?.explore)runTelemetry.explore.rift++;if(rift.siteId){const s=worldSites.find(v=>v.id===rift.siteId);if(s){s.claimed=true;s.active=false;}}rift=null;$('objectiveBadge').style.display='none'; updateHUD();
}
function failGeneRift(){
  if(!rift)return;
  let x=rift.x,y=rift.y;if(rift.siteId){const s=worldSites.find(v=>v.id===rift.siteId);if(s){s.claimed=true;s.active=false;}}riftFail++;rift=null;$('objectiveBadge').style.display='none';
  flash('RIFT COLLAPSED · SWARM INCOMING',1100);beep(80,.2,'sawtooth',.035);
  particles.push({kind:'deathRing',x,y,r:8,max:60,life:.42,maxLife:.42});
  for(let i=0;i<4;i++)spawnEnemy('runner');
  for(let i=0;i<2;i++)spawnEnemy(t>120?'spitter':'crawler');
}
function updateGeneRift(dt){
  if(!rift)return;
  rift.life-=dt;
  const d=Math.hypot(player.x-rift.x,player.y-rift.y);
  if(d<rift.r+player.r+7)rift.hold=Math.min(rift.need,rift.hold+dt);
  else rift.hold=Math.max(0,rift.hold-dt*.7);
  const pct=Math.floor(rift.hold/rift.need*100);
  $('objectiveBadge').textContent='GENE RIFT · '+pct+'% · '+Math.max(0,Math.ceil(rift.life))+'s';
  if(rift.hold>=rift.need)completeGeneRift();
  else if(rift&&rift.life<=0)failGeneRift();
}

function spawnPurgeWave(count=3,tier=1,force=false){
  if(!force&& !directorCanStart('purge'))return false;directorHold(force ? .35 : 1.0);
  flash('CONTAINMENT PURGE · MOVE',1000);beep(115,.18,'sawtooth',.035);
  for(let i=0;i<count;i++){
    let x,y,tries=0,r=42+tier*4,p;
    do{p=worldPointInView(70);x=p.x;y=p.y;tries++}while(tries<16&&Math.hypot(x-player.x,y-player.y)<90);
    purges.push({x,y,r,warn:1.15,active:1.65+tier*.15,tick:0,tier});
  }
  return true;
}
function updatePurges(dt){
  for(const z of purges){
    if(z.warn>0){z.warn-=dt;continue}
    z.active-=dt;z.tick-=dt;
    if(z.active>0 && Math.hypot(player.x-z.x,player.y-z.y)<z.r+player.r && z.tick<=0){
      playerDamage(7+z.tier*2);z.tick=.45;cameraShake=Math.max(cameraShake,3);
    }
  }
  purges=purges.filter(z=>z.warn>0||z.active>0);
}

