  if(route?.tier?.id==='hazard')return '! HAZARD';
  if(route?.zone==='cultivation'&&(player.maxHp?player.hp/player.maxHp:1)<.8)return 'RECOVERY';
  if(route?.zone==='disposal')return 'DNA / ACID';
