const _objectivePointerCandidatesV410=objectivePointerCandidates;
objectivePointerCandidates=function(){
  let arr=_objectivePointerCandidatesV410().map(o=>({...o}));
  for(const o of arr){if(o.label==='GATE')o.priority=Math.max(o.priority||0,140);else if(o.label==='RIFT')o.priority=Math.max(o.priority||0,130);}
  const open=worldSites.filter(s=>s.type==='zoneEvent'&&!s.claimed&&!s.arenaHidden),anomaly=open.filter(s=>ensureZoneEventTier(s).id==='anomaly').sort((a,b)=>dist2(player,a)-dist2(player,b))[0];
  if(anomaly){const hit=arr.find(o=>Math.hypot(o.x-anomaly.x,o.y-anomaly.y)<3);if(hit){hit.label='★ANOMALY';hit.color='#ffe06d';hit.priority=Math.max(hit.priority||0,118);}else arr.push({x:anomaly.x,y:anomaly.y,label:'★ANOMALY',color:'#ffe06d',priority:118});}
  if(!anomaly){const hazard=open.filter(s=>ensureZoneEventTier(s).id==='hazard').sort((a,b)=>dist2(player,a)-dist2(player,b))[0];if(hazard&&!arr.some(o=>Math.hypot(o.x-hazard.x,o.y-hazard.y)<3))arr.push({x:hazard.x,y:hazard.y,label:'!HAZARD',color:'#ffae55',priority:84});}
  const seen=new Set();arr=arr.filter(o=>{const k=Math.round(o.x/3)+':'+Math.round(o.y/3);if(seen.has(k))return false;seen.add(k);return true;});
  return arr.sort((a,b)=>(b.priority||0)-(a.priority||0)||dist2(player,a)-dist2(player,b)).slice(0,3);
};
const _organDamageMulV410=organDamageMul;
organDamageMul=function(e,kind){
  let m=_organDamageMulV410(e,kind);
  if(zoneSetActive('facility'))m*=1.05;
  if(zoneSetActive('cultivation')&&(player.maxHp?player.hp/player.maxHp:1)>=.85)m*=1.08;
  if(zoneSetActive('disposal')&&kind==='acid')m*=1.12;
  if(zoneSetActive('titan')&&(kind==='tail'||kind==='leg'))m*=1.10*(e&&(e.elite||e.finalBoss)?1.08:1);
  return m;
};
const _playerDamageV410=playerDamage;
playerDamage=function(dmg){if(zoneSetActive('facility'))dmg*=.95;return _playerDamageV410(dmg);};
