// ===== EVOLVE V522: campaign home =====
// The selected stage is independent of the furthest unlocked stage.
// Original image bytes are reused; the chamber and icons are CSS/SVG.
let homeSelectedStageV522=1,homePageV522='battle',homeReadyV522=false,homeLoadErrorV522='';
function stageUnlockFromSaveV522(m){
 let best=Math.max(1,m.stage|0||1,m.unlockedStageV522|0||1);
 if(Array.isArray(m.claimedStages))for(const s of m.claimedStages){if(Number.isInteger(s)&&s>=1&&s<=99)best=Math.max(best,Math.min(99,s+1));}
 return best;
}
function homeUnlockedStageV522(){return Math.max(1,meta.unlockedStageV522|0||1);}
function homeLanguageV522(){return window.EVOLVE_I18N?.getLanguage?.()||(()=>{try{return localStorage.getItem('EVOLVE_V575_TEST_UI_LANGUAGE_V1')==='ko'?'ko':'en';}catch(_){return 'en';}})();}
function homeTextV522(en,ko){return homeLanguageV522()==='ko'?ko:en;}
function homeSetTextV522(id,text){const el=$(id);if(el&&el.textContent!==text)el.textContent=text;}
function homeBossV522(s){
 if(s===20)return ['VENOM TITAN','베놈 타이탄'];
 if(campaignMilestone(s)==='OMEGA')return ['ABYSS MATRIARCH','어비스 매트리아크'];
 if(campaignMilestone(s)==='APEX')return ['ORIGIN COLOSSUS','오리진 콜로서스'];
 if(meta.route==='cryo')return ['FROST TITAN','프로스트 타이탄'];
 if(meta.route==='gene')return ['ABERRANT TITAN','어베런트 타이탄'];
 if(meta.route==='inferno')return ['PYRE TITAN','파이어 타이탄'];
 return ['BIO TITAN','바이오 타이탄'];
}
